def run(root):
    p=authorize(root);balance=read_bound_json(root/'ACTUAL_FORCE_BALANCE_REGRESSION.json');assert balance['passed'];assert not (root/'FINAL_REVIEW.json').exists();ledger=read_bound_json(root/'COST.json');items=[];cost=0
    for x in ledger['reservations']:
        f=Path(x['output'])/'REPORT.json';assert f.exists(),'unresolved reservation';n=read_bound_json(f)['physics_steps'];assert n<=x['maximum_steps'];cost+=n;items.append(dict(actual_steps=n,report=_file_binding(f),reservation=x))
